function escKit(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}document.addEventListener('DOMContentLoaded',async()=>{const el=document.getElementById('selecoes-reais');try{const kits=await apiFetch('/operacoes/kits');el.innerHTML=kits.length?kits.map(k=>`<article class="cartao-produto"><div class="imagem-produto">${k.imagem_url?`<img src="${escKit(k.imagem_url)}" alt="${escKit(k.nome)}" loading="lazy">`:''}</div><div class="info-produto"><div class="categoria-produto">Kit Lúmina</div><h3>${escKit(k.nome)}</h3><p>${escKit(k.descricao||'Seleção de produtos Lúmina')}</p><small>${(k.itens||[]).map(i=>`${escKit(i.nome)} ×${Number(i.quantidade||1)}`).join(', ')}</small><div class="preco">${(window.LUMINA?window.LUMINA.money(Number(k.preco_eur)):Number(k.preco_eur).toLocaleString('pt-PT',{style:'currency',currency:'EUR'}))}</div><p class="nota-frete">Para encomendar este kit, contacte a equipa. A compra como pacote será ativada quando o checkout suportar preço de kit de forma atómica.</p></div></article>`).join(''):'<p>Ainda não há kits publicados.</p>';}catch(e){el.textContent='Não foi possível carregar os kits. Tente novamente mais tarde.';}});
